def solve(weights, values, capacity):
    # 0/1 knapsack using 1D DP
    n = len(weights)
    if capacity < 0:
        return 0
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        # iterate backwards to avoid reuse
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

def solve(path):
    """Simplify an absolute Unix path.
    Resolve '.' and '..' components, collapse multiple slashes, and ensure the
    result has no trailing slash (except for the root '/').
    """
    # Split by '/' and process components
    components = path.split('/')
    stack = []
    for comp in components:
        if comp == '' or comp == '.':
            # empty component (due to leading, trailing or repeated slashes) or current dir – skip
            continue
        if comp == '..':
            if stack:
                stack.pop()
            # if stack empty, we stay at root – nothing to do
            continue
        # regular directory name
        stack.append(comp)
    # Build the simplified path
    if not stack:
        return '/'
    return '/' + '/'.join(stack)

