def solve(mat):
    # empty matrix determinant is 1 per spec
    if not mat:
        return 1
    n = len(mat)
    # make a copy as floats? Use Fraction for exactness
    from fractions import Fraction
    a = [[Fraction(x) for x in row] for row in mat]
    det = Fraction(1)
    for i in range(n):
        # find pivot
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            det = -det
        det *= a[i][i]
        # normalize row i
        piv_val = a[i][i]
        for j in range(i, n):
            a[i][j] /= piv_val
        # eliminate below
        for k in range(i+1, n):
            factor = a[k][i]
            if factor != 0:
                for j in range(i, n):
                    a[k][j] -= factor * a[i][j]
    # det is product of diagonal (already accounted) but we normalized rows to 1, so det holds product
    # convert to int
    return int(det)

