def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting O(n log n)."""
    import bisect
    dp=[]
    for x in nums:
        i=bisect.bisect_left(dp, x)
        if i==len(dp):
            dp.append(x)
        else:
            dp[i]=x
    return len(dp)

