def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting (n log n) algorithm.
    """
    import bisect
    tails = []
    for x in nums:
        # find insertion point in tails
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

